SELECT sku, count(*) n, min(date) mn, max(date) mx, count(DISTINCT date) nd,
       min(revenue_inr/nullif(units_sold,0)) min_up, max(revenue_inr/nullif(units_sold,0)) max_up
FROM store.daily_sales GROUP BY 1 ORDER BY 1;

SELECT sku_scanned, unit_price, min(bill_ts)::date mn, max(bill_ts)::date mx, count(*) n, sum(qty) qty
FROM store.pos_lines
GROUP BY 1,2 ORDER BY 1,2;

SELECT bill_id, bill_ts, count(*) lines FROM store.pos_lines
WHERE bill_ts >= TIMESTAMP '2026-06-01' AND bill_ts < TIMESTAMP '2026-06-02'
GROUP BY 1,2 ORDER BY bill_id LIMIT 30;

SELECT bill_id, bill_ts, line, sku_scanned, qty FROM store.pos_lines
WHERE bill_ts >= TIMESTAMP '2026-06-01 07:00' AND bill_ts < TIMESTAMP '2026-06-01 07:05'
ORDER BY bill_ts, bill_id, line LIMIT 60;
